  "components.skeleton-key.name": "Skeleton Key",
  "components.slime-core.desc": "On Pickup:\nSummon a trio of friendly Void Slimes",
  "components.slime-core.name": "Slime Core",
  "components.starfire-ingot.desc": "On Pickup:\nSummon a pair of Starfire Chimeras to fight for you",
  "components.starfire-ingot.name": "Starfire Ingot",
  "components.stormglass-eye.desc": "On Pickup:\nSummon a Storm Cloud over each enemy in line of sight\nEach cloud has a 50% chance to deal 25 Lightning damage each turn\nStorm Clouds last for 5 turns\nThis effect repeats every 6 turns until the end of the level",
  "components.stormglass-eye.name": "Stormglass Eye",
  "components.stormsong-note.desc": "On Craft:\nIf the crafted equipment has the Ice tag, it summons Blizzards at random locations when you manually cast an Ice spell\nIf the crafted equipment has the Lightning tag, it summons Storm Clouds at random locations when you manually cast a Lightning spell\nThe number of clouds created is equal to the spell's level\nThe damage and duration of the clouds scale with the equipment",
  "components.stormsong-note.name": "Stormsong Note",
  "components.thundergod-s-fang.desc": "On Pickup:\nEnemies with the Lightning tag and less HP than you join your team",
  "components.thundergod-s-fang.name": "Thundergod's Fang",
  "components.timelost-inscription.desc": "On Pickup:\nFor the next 6 turns, when you cast a Sorcery spell, each of your other spells regains a charge",
  "components.timelost-inscription.name": "Timelost Inscription",
  "components.umbral-resin.desc": "On Pickup:\nGain 100% resistance to Dark and Poison damage for the remainder of the level",
  "components.umbral-resin.name": "Umbral Resin",
  "components.voidstone-shard.desc": "On Pickup:\nRegain all spell charges",
  "components.voidstone-shard.name": "Voidstone Shard",
  "components.voltaic-ash.desc": "On Pickup:\nFire a beam toward each other unit in your line of sight\nEach beam deals 16 Fire or Lightning damage\nThis effect repeats every 6 turns until the end of the level",
  "components.voltaic-ash.name": "Voltaic Ash",
  "components.votive-candle.desc": "On Pickup:\nHeal 10 HP per turn for the next 12 turns",
  "components.votive-candle.name": "Votive Candle",
  "components.warlord-s-skull.desc": "On Craft:\nIf the crafted equipment would provide bonuses to damage, duration, range, or num_targets, it provides those bonuses to minion_damage, minion_duration, minion_range, or num_summons instead",
  "components.warlord-s-skull.name": "Warlord's Skull",
  "components.warped-dragon-egg.desc": "On Pickup:\nA random Conjuration spell you know gains +3 minion damage",
  "components.warped-dragon-egg.name": "Warped Dragon Egg",
  "components.watcher-stone.desc": "On Pickup:\nSummon a friendly Watcher",
  "components.watcher-stone.name": "Watcher Stone",
  "components.wildflower.desc": "On Pickup:\nRemove poison and heal for 50 HP",
  "components.wildflower.name": "Wildflower",
  "components.worldstone-socket.desc": "On Craft:\nIf the crafted equipment has the radius attribute, it gains +2 radius",
  "components.worldstone-socket.name": "Worldstone Socket",
