  "equipment.druid-s-dibble.desc": "Every other Nature spell you cast summons a Flytrap near the target",
  "equipment.druid-s-dibble.name": "Druid's Dibble",
  "equipment.dwarf-hat.desc": "At the beginning of each level, if you know at least seven spells, summon 7 Duergar",
  "equipment.dwarf-hat.name": "Dwarf Hat",
  "equipment.earthmeld-boots.desc": "Each turn, heal 3 HP unless you moved",
