  "equipment.earthtroll-armor.name": "Earthtroll Armor",
  "equipment.earthwrath.desc": "When you cast a Nature or Chaos spell, send out tremors along the ground from the target to nearby enemies\nEach tremor deals 18 Physical damage to the target and all units in its path\nThe number of targets is equal to the level of the spell\nThe tremors can target enemies up to 4 tiles away",
