  "equipment.eldritch-mantle.desc": "Tentacles drag the nearest 3 enemies along paths toward the wearer each turn\nTentacles deal 12 Arcane damage to their targets",
  "equipment.eldritch-mantle.name": "Eldritch Mantle",
  "equipment.electroplasm-ampule.desc": "When allies are summoned, they are afflicted with Electroplasm\nElectroplasm deals 1 Lightning damage to afflicted units each turn\nIf a unit with Electroplasm dies to Lightning damage, an Electric Slime is summoned nearby",
