  "equipment.evermelting-cube.name": "Evermelting Cube",
  "equipment.exploding-boots.desc": "Every 8 steps, cast Flame Burst\n8 steps until cast",
  "equipment.exploding-boots.name": "Exploding Boots",
  "equipment.explosive-spore-manual.desc": "While enemies live, cast Combust Poison at the end of each turn",
  "equipment.explosive-spore-manual.name": "Explosive Spore Manual",
  "equipment.eye-helm.desc": "When you cast an Eye spell, gain 3 SH, up to a max of 20",
