  "equipment.eye-of-mot.name": "Eye of Mot",
  "equipment.eye-of-tamtu.name": "Eye of Tamtu",
  "equipment.eye-rock-pendant.name": "Eye Rock Pendant",
  "equipment.fae-plate.desc": "Gain 1 SH each turn, up to a max of 3",
  "equipment.fae-plate.name": "Fae Plate",
  "equipment.fae-thorn-staff.desc": "When you cast an Arcane or Nature spell, summon 3 temporary Fae Thorns near the target",
