  "equipment.icy-chill-mask.name": "Icy Chill Mask",
  "equipment.icy-claw-staff.desc": "When your allies damage enemies, redeal half the damage dealt as Ice damage",
  "equipment.icy-claw-staff.name": "Icy Claw Staff",
