  "equipment.iron-legion-s-banner.name": "Iron Legion's Banner",
  "equipment.jaculus-idol.desc": "Dragon allies you summon gain quickstep",
  "equipment.jaculus-idol.name": "Jaculus Idol",
  "equipment.jade-shard.desc": "Each turn, enemies adjacent to your Living and Nature allies are poisoned for 12 turns",
  "equipment.jade-shard.name": "Jade Shard",
