  "equipment.metallurgy-mitts.name": "Metallurgy Mitts",
  "equipment.minion-regeneration-amulet.desc": "Each turn, heal each of your allies for 2 HP",
  "equipment.minion-regeneration-amulet.name": "Minion Regeneration Amulet",
  "equipment.molten-carapace.desc": "You are immune to freeze",
  "equipment.molten-carapace.name": "Molten Carapace",
  "equipment.monkey-skull-amulet.name": "Monkey Skull Amulet",
