  "equipment.multicolored-rage-rod.name": "Multicolored Rage Rod",
  "equipment.multimancer-s-staff.name": "Multimancer's Staff",
  "equipment.nature-staff.name": "Nature Staff",
  "equipment.neanderthal-s-tooth.name": "Neanderthal's Tooth",
  "equipment.necromancer-s-staff.name": "Necromancer's Staff",
  "equipment.necrosis-blade.desc": "When an enemy takes Dark damage, it has a 60% chance to be afflicted with 3 turns of necrosis",
  "equipment.necrosis-blade.name": "Necrosis Blade",
  "equipment.necrostatic-staff.desc": "Each of your Undead allies grants you a +1 damage bonus to Lightning spells and equipment until they die",
  "equipment.necrostatic-staff.name": "Necrostatic Staff",
  "equipment.nightmare-hexbag.desc": "Each turn, deal 4 Dark damage to 25 random enemies currently afflicted with sleep",
