  "equipment.paralyzing-venom.desc": "When an enemy takes Poison damage, it has a 30% chance to be afflicted with 2 turns of stun",
  "equipment.paralyzing-venom.name": "Paralyzing Venom",
  "equipment.pedantic-pendant.name": "Pedantic Pendant",
  "equipment.philosopher-s-stone.desc": "This item gains the tags of the components used to craft it\nWhen you cast a spell that shares a tag with this item, there is a 10% chance for all of your spells to regain a charge",
  "equipment.philosopher-s-stone.name": "Philosopher's Stone",
