  "equipment.plague-doctor-s-cane.name": "Plague Doctor's Cane",
  "equipment.plague-doctor-s-mask.desc": "You are immune to necrosis",
  "equipment.plague-doctor-s-mask.name": "Plague Doctor's Mask",
  "equipment.plague-doctor-s-robe.desc": "Each turn, inflict a stack of permanent necrosis on other units within 5 tiles",
  "equipment.plague-doctor-s-robe.name": "Plague Doctor's Robe",
  "equipment.plaguebringer.desc": "Redeal damage dealt to enemies by Demon allies as Poison damage",
  "equipment.plaguebringer.name": "Plaguebringer",
  "equipment.plasmic-distributor.desc": "When allies are summoned adjacent to you, cast Vampiricism on them\nThis item can activate up to 7 times each level\nVampiricism Bestowed: 0 / 7",
  "equipment.plasmic-distributor.name": "Plasmic Distributor",
  "equipment.prism-of-shattered-sensations.desc": "When an enemy heals or takes damage they are stunned for 1 turns",
  "equipment.prism-of-shattered-sensations.name": "Prism of Shattered Sensations",
