  "grimoire.upgrades.706.name": "Chaos Seal",
  "grimoire.upgrades.707.desc": "Searing Seal gains 10 Minion Health\nSearing Seal gains 5 Minion Range\nSearing Seal gains 5 Minion Damage\nFor every 100 charges stored, summon a Fire Spirit\nAdds the Conjuration tag",
