  "grimoire.upgrades.718.name": "Razor Ice",
  "grimoire.upgrades.72.desc": "Boiling Blood gains 3 Damage\nBoiling Blood gains 2 Radius\nAffected units receive a damage aura that deals 3 Fire damage to enemies within 2 tiles each turn\nAffected units explode on death, dealing 30 Fire damage to units within 2 tiles",
  "grimoire.upgrades.72.name": "Combustion Point",
  "grimoire.upgrades.721.desc": "The shrapnel can penetrate and destroy walls\nIf it would destroy a wall besides the initial target, there is a 25% chance to cast Shrapnel Blast on that wall",
