  "grimoire.upgrades.788.desc": "Deal both Lightning and Ice damage to affected tiles",
  "grimoire.upgrades.788.name": "Dual Nova",
  "grimoire.upgrades.789.desc": "Storm Burst gains 3 Max Channel\nStorm Burst can be channeled for up to 3 turns\nIf the ritual is completed, Storm Burst's radius and duration increase by 1 for the remainder of the level\nAdds the Ritual tag",
  "grimoire.upgrades.789.name": "Ritual of Storms",
  "grimoire.upgrades.79.desc": "Damage dealt by Metallic allies' bones is multiplied by 4\nAdds the Metallic tag",
  "grimoire.upgrades.79.name": "Piston Spears",
  "grimoire.upgrades.790.desc": "Storm Burst gains 36 Minion Health\nStorm Burst gains 11 Minion Damage\nStorm Burst gains 6 Minion Range\nSummon a Storm Spirit for every 60 damage dealt in a single cast\nAdds the Conjuration tag",
  "grimoire.upgrades.790.name": "Spirit Nova",
  "grimoire.upgrades.791.desc": "Grant affected allies Ice and Lightning immunity for 4 turns instead of harming them",
