  "grimoire.upgrades.793.desc": "Storm Drakes can cast your Chain Lightning on a 9 turn cooldown",
  "grimoire.upgrades.793.name": "Dragon Mage",
  "grimoire.upgrades.794.desc": "Storm Drakes gain 5 HP when you cast a Lightning spell targeting a tile in their line of sight",
  "grimoire.upgrades.794.name": "Spirit Drakes",
  "grimoire.upgrades.795.desc": "Storm Drake gains 2 Num Summons\nWhen you cast Storm Drake, up to 2 Storm Clouds in line of sight of the target are converted into Storm Drakes",
  "grimoire.upgrades.795.name": "Storm Summoning",
  "grimoire.upgrades.796.desc": "When you cast this spell, if there is room, summon Stormcrest instead of a Storm Drake\nCan only activate once each level",
  "grimoire.upgrades.796.name": "Stormcrest",
  "grimoire.upgrades.798.desc": "Storm Walk gains quickcast",
  "grimoire.upgrades.798.name": "Quickcast",
  "grimoire.upgrades.799.desc": "Gain a boon depending on the kind of cloud you Storm Walk to\nRain Clouds remove all debuffs\nBlizzards grant 3 SH\nLightning Clouds grant 3 turns of quickstep",
  "grimoire.upgrades.799.name": "Storm Boon",
  "grimoire.upgrades.8.desc": "Annihilate also deals Ice, Holy, Dark, and Arcane damage hits\nAdds the Ice tag\nAdds the Holy tag\nAdds the Dark tag\nAdds the Arcane tag",
  "grimoire.upgrades.8.name": "Comprehensive Annihilation",
  "grimoire.upgrades.800.desc": "Cast Storm Burst after arriving at your destination",
  "grimoire.upgrades.800.name": "Storm Surge",
  "grimoire.upgrades.801.desc": "Leave behind a line of matching clouds between you and your destination",
  "grimoire.upgrades.801.name": "Weathered Traveler",
  "grimoire.upgrades.803.desc": "Summon Blade gains 2 Num Summons\nSummon 2 blades instead of one",
  "grimoire.upgrades.803.name": "Bladeworks",
  "grimoire.upgrades.804.desc": "Summon Blade gains 8 Max Channel\nYou may channel this spell for 8 turns\nIf you complete the ritual, gain the Blade Rites buff for 8 turns, which summons a blade near you each turn\nAdds the Ritual tag",
  "grimoire.upgrades.804.name": "Ritual of Blades",
  "grimoire.upgrades.805.desc": "Summon Blade gains 3 Duration\nThe blades' leap attack inflicts 3 turns of bleed\nAdds the Blood tag",
