  "grimoire.upgrades.808.desc": "Summon half as many Bone Knight Archers to accompany the Bone Knights",
  "grimoire.upgrades.808.name": "Bone Squadron",
  "grimoire.upgrades.809.desc": "Summon Bone Knights gains 20 Minion Health\nKnights receive the Metallic tag, gaining Lightning immunity along with increased resistance to Fire, Ice, and Physical damage\nAdds the Metallic tag",
