  "grimoire.upgrades.811.name": "Knightmares",
  "grimoire.upgrades.813.desc": "Always summon the Dragon Wizard\nAdds the Dragon tag",
  "grimoire.upgrades.813.name": "Dragon Wizard",
  "grimoire.upgrades.814.desc": "Summon Wizard gains -1 Requires LoS\nSummon Wizard gains 99 Range",
